CREATE TABLE IF NOT EXISTS batches (id TEXT PRIMARY KEY, sequence INTEGER NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'Not researched', created_at TEXT NOT NULL, research_started_at TEXT, research_completed_at TEXT, review_completed_at TEXT, publication_completed_at TEXT);
CREATE TABLE IF NOT EXISTS batch_employers (batch_id TEXT NOT NULL REFERENCES batches(id), employer_id TEXT NOT NULL REFERENCES employers(id), ordinal INTEGER NOT NULL, PRIMARY KEY(batch_id, employer_id), UNIQUE(employer_id));
CREATE TABLE IF NOT EXISTS employer_research (batch_id TEXT NOT NULL REFERENCES batches(id), employer_id TEXT NOT NULL REFERENCES employers(id), status TEXT NOT NULL DEFAULT 'Not researched', started_at TEXT, completed_at TEXT, limitation_reason TEXT, manual_follow_up INTEGER NOT NULL DEFAULT 0, acknowledged_at TEXT, acknowledgement_note TEXT, PRIMARY KEY(batch_id, employer_id));
